def main() -> None:
    connection = sqlite3.connect(DB_PATH)
    try:
        existing = connection.execute(
            "SELECT id FROM posts WHERE slug = ? AND lang = 'ru'", (SLUG,)
        ).fetchone()
        values = (TITLE, CONTENT, EXCERPT, "2026-10-08", f"/ru/blog/{SLUG}/")
        if existing:
            connection.execute(
                """
                UPDATE posts
                SET title = ?, content = ?, excerpt = ?, date = ?, link = ?
                WHERE slug = ? AND lang = 'ru'
                """,
                (*values, SLUG),
            )
        else:
            connection.execute(
                """
                INSERT INTO posts (slug, title, content, excerpt, date, lang, link)
                VALUES (?, ?, ?, ?, ?, 'ru', ?)
                """,
                (SLUG, TITLE, CONTENT, EXCERPT, "2026-10-08", f"/ru/blog/{SLUG}/"),
            )
        connection.commit()
    finally:
        connection.close()


if __name__ == "__main__":
    main()
